/*
 * Renders README.md as a web page and adds the sort combo box under "Games".
 *
 * README.md is read fresh on every visit, so editing it updates the page with no
 * build step. Facts the README does not state (date added, price, genre and so
 * on) come from data/games.json, generated by tools/update_data.py, and from
 * data/overrides.json, written by hand. Overrides always win.
 *
 * Keep parseEntries in step with parse_entries in tools/update_data.py: both
 * must produce the same keys.
 */
(function () {
  'use strict';

  var SECTIONS = {
    'games': 'games',
    'accidentally accessible games': 'accidental',
    'ios games': 'ios'
  };

  /* The order of the README's own glossary, most accessible first. */
  var LEVELS = [
    { id: 'full', label: 'Fully accessible', pattern: /full(?:y)?\s+access/i },
    { id: 'mostly', label: 'Mostly accessible', pattern: /mostly\s+access/i },
    { id: 'playable', label: 'Playable', pattern: /playable/i },
    { id: 'partial', label: 'Partially accessible', pattern: /partial+y?\s+access|mostly\s+inaccess/i },
    { id: 'wip', label: 'Work in progress', pattern: /work\s+in\s+progress/i },
    { id: 'unknown', label: 'Limited information', pattern: /limited\s+information|no\s+information/i }
  ];

  var SETUPS = [
    { id: 'builtin', label: 'No mod needed' },
    { id: 'mod', label: 'Needs a mod' },
    { id: 'emulator', label: 'Needs an emulator' }
  ];

  var PLATFORMS = [
    { id: 'all', label: 'All platforms', pattern: /all\s+platforms/i },
    { id: 'pc', label: 'PC', pattern: /\bpc\b/i },
    { id: 'playstation', label: 'PlayStation', pattern: /\bps[345]\b|playstation/i },
    { id: 'xbox', label: 'Xbox', pattern: /\bxbox\b/i },
    { id: 'switch', label: 'Nintendo Switch', pattern: /\bswitch\b/i },
    { id: '3ds', label: 'Nintendo 3DS', pattern: /\b3ds\b/i },
    { id: 'browser', label: 'Web browser', pattern: /\bbrowser\b/i },
    { id: 'android', label: 'Android', pattern: /\bandroid\b/i },
    { id: 'ios', label: 'iOS', pattern: /\bios\b/i }
  ];

  var PRICE_BANDS = [
    { label: 'Free', test: function (p) { return p === 0; } },
    { label: 'Under $5', test: function (p) { return p > 0 && p < 5; } },
    { label: '$5 to $9.99', test: function (p) { return p >= 5 && p < 10; } },
    { label: '$10 to $19.99', test: function (p) { return p >= 10 && p < 20; } },
    { label: '$20 to $39.99', test: function (p) { return p >= 20 && p < 40; } },
    { label: '$40 and over', test: function (p) { return p >= 40; } }
  ];
  var NO_PRICE = 'No fixed price recorded';

  var RATING_BANDS = [
    { label: 'Rated 90% or higher', test: function (r) { return r >= 90; } },
    { label: 'Rated 70% to 89%', test: function (r) { return r >= 70 && r < 90; } },
    { label: 'Rated 40% to 69%', test: function (r) { return r >= 40 && r < 70; } },
    { label: 'Rated below 40%', test: function (r) { return r < 40; } }
  ];
  var NO_RATING = 'Not enough ratings recorded';
  var MIN_RATINGS = 10;

  var MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August',
    'September', 'October', 'November', 'December'];

  var collator = new Intl.Collator('en', { numeric: true, sensitivity: 'base' });

  var dataUpdated = '';
  var historyStart = '';

  /* --- Reading a line of the list ------------------------------------------ */

  function repairLine(text) {
    return text
      .replace(/^\(([^\]]+)\]\(/, '[$1](')              // (Osu!](url)
      .replace(/\[([^\]\[()]+)\[\(/g, '[$1](')          // [text,[(url)
      .replace(/\[([^\]\[()]+)\((https?:\/\/)/g, '[$1]($2') // [text(url)
      .replace(/\[([^\]\[()]+)\[\)/g, '[$1]')           // [text[)
      .replace(/^([^\[(]+?) \((https?:\/\/[^\s)]+)\)/, '[$1]($2)'); // text (url)
  }

  function linkPattern() {
    return /\[([^\]]*)\]\(((?:[^()\s]|\([^()\s]*\))+)\)/g;
  }

  function entryTitle(text) {
    var match = /^\[([^\]]*)\]/.exec(text);
    var title = match ? match[1] : text.split(/[\[(]/)[0];
    title = title.split(/\s+e\.g\./i)[0];
    return title.replace(/^[ ,.;:]+|[ ,.;:]+$/g, '');
  }

  function slug(text) {
    return text.normalize('NFKD').replace(/[̀-ͯ]/g, '').toLowerCase()
      .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  }

  /* Splits a line into text and links, tidying the stray brackets the list's
     entry format leaves behind so a screen reader does not read them out. */
  function tokenize(line) {
    var tokens = [];
    var pattern = linkPattern();
    var last = 0;
    var match;
    while ((match = pattern.exec(line))) {
      if (match.index > last) tokens.push({ text: line.slice(last, match.index) });
      var label = match[1];
      tokens.push({ text: label.replace(/,\s*$/, ''), href: match[2] });
      if (/,\s*$/.test(label)) tokens.push({ text: ',' });
      last = pattern.lastIndex;
    }
    if (last < line.length) tokens.push({ text: line.slice(last) });

    /* Remove brackets with no partner, counting across the whole line. */
    var open = [];
    tokens.forEach(function (token, t) {
      if (token.href) return;
      var chars = token.text.replace(/[\[\]]/g, '').split('');
      token.chars = chars;
      chars.forEach(function (ch, c) {
        if (ch === '(') open.push([t, c]);
        else if (ch === ')') {
          if (open.length) open.pop();
          else chars[c] = '';
        }
      });
    });
    open.forEach(function (at) { tokens[at[0]].chars[at[1]] = ''; });
    tokens.forEach(function (token) {
      if (!token.href) {
        token.text = token.chars.join('');
        delete token.chars;
      }
    });

    /* Tidy the text between links. */
    var merged = [];
    tokens.forEach(function (token) {
      var previous = merged[merged.length - 1];
      if (previous && !previous.href && !token.href) previous.text += token.text;
      else merged.push(token);
    });
    merged.forEach(function (token) {
      if (token.href) return;
      token.text = token.text
        .replace(/\s+/g, ' ')
        .replace(/,(\s*,)+/g, ',')
        .replace(/[,\s]+\s([-–—])\s*/g, ' $1 ')
        .replace(/\s+,/g, ',');
    });
    return merged;
  }

  function appendTokens(parent, tokens) {
    tokens.forEach(function (token) {
      if (token.href && /^https?:/i.test(token.href)) {
        var link = document.createElement('a');
        link.href = token.href;
        link.textContent = token.text;
        parent.appendChild(link);
      } else {
        parent.appendChild(document.createTextNode(token.text));
      }
    });
  }

  /* --- Working out what the README says about an entry ---------------------- */

  function classifyAccess(text) {
    var best = null;
    var bestAt = Infinity;
    LEVELS.forEach(function (level) {
      var found = text.search(level.pattern);
      if (found !== -1 && found < bestAt) {
        best = level.id;
        bestAt = found;
      }
    });
    return best;
  }

  function levelRank(id) {
    return LEVELS.findIndex(function (level) { return level.id === id; });
  }

  function linkedPlain(tokens) {
    return tokens.map(function (token) { return token.text; }).join('');
  }

  function unlinkedPlain(tokens) {
    return tokens.filter(function (token) { return !token.href; })
      .map(function (token) { return token.text; }).join(' ');
  }

  function describe(entry) {
    var tokens = tokenize(entry.line);
    var free = unlinkedPlain(tokens);
    /* Game and mod names are links, so the first dash in the rest of the line
       is the one that introduces the accessibility status. */
    var dash = free.search(/\s[-–—]\s?/);
    var before = dash === -1 ? free : free.slice(0, dash);
    var status = dash === -1 ? free : free.slice(dash);
    var childLines = entry.children.map(function (child) { return linkedPlain(tokenize(child)); });

    var access = classifyAccess(status);
    if (!access) {
      childLines.forEach(function (child) {
        var level = classifyAccess(child);
        if (level && (!access || levelRank(level) < levelRank(access))) access = level;
      });
    }
    entry.access = access || (entry.section === 'accidental' ? 'playable' : 'unknown');

    var whole = tokens.slice(tokens[0] && tokens[0].href ? 1 : 0)
      .map(function (token) { return token.text; }).join(' ') + ' ' + childLines.join(' ');
    if (entry.section === 'ios' || /without\s+mods?\b/i.test(whole)) entry.setup = 'builtin';
    else if (/emulat/i.test(whole)) entry.setup = 'emulator';
    else if (/\b(?:mods?|modpack|fork|add-?on|port|project|accessible version)\b/i.test(whole)) entry.setup = 'mod';
    else entry.setup = 'builtin';

    entry.audioDescription = /audio[- ]descri/i.test(whole);

    entry.platforms = PLATFORMS.filter(function (platform) {
      return platform.pattern.test(before);
    }).map(function (platform) { return platform.id; });
    if (entry.section === 'ios' && entry.platforms.indexOf('ios') === -1) entry.platforms.push('ios');
    if (!entry.platforms.length) {
      var first = (tokens.filter(function (token) { return token.href; })[0] || {}).href || '';
      if (/steampowered|gog\.com|itch\.io|microsoft\.com/.test(first)) entry.platforms = ['pc'];
      else if (/nintendo\.com/.test(first)) entry.platforms = [/3ds/.test(first) ? '3ds' : 'switch'];
      else if (/playstation\.com/.test(first)) entry.platforms = ['playstation'];
    }
    entry.tokens = tokens;
  }

  /* Pulls the three game lists out of the README, leaving everything else in
     order. Returns the page as a list of blocks. */
  function parseEntries(markdown) {
    var blocks = [];
    var section = null;
    var current = null;
    var list = null;
    var firstHeading = true;

    markdown.split(/\r?\n/).forEach(function (raw) {
      var heading = /^(#+)\s+(.*\S)\s*$/.exec(raw);
      if (heading) {
        var level = heading[1].length;
        section = SECTIONS[heading[2].toLowerCase()] || null;
        current = null;
        list = null;
        /* The README has a second top-level heading (iOS Games). One h1 per page. */
        if (level === 1 && !firstHeading) level = 2;
        firstHeading = false;
        blocks.push({ type: 'heading', level: level, text: heading[2], section: section });
        if (section) list = { type: 'games', section: section, entries: [] };
        return;
      }
      if (/^\s*$/.test(raw)) return;
      if (/^-{3,}\s*$/.test(raw)) {
        blocks.push({ type: 'rule' });
        current = null;
        return;
      }
      var item = /^(\s*)-\s+(.*)$/.exec(raw);
      if (item) {
        var text = repairLine(item[2].trim());
        var nested = item[1].length > 0;
        if (section) {
          if (nested && current) {
            current.children.push(text);
          } else {
            current = { section: section, line: text, children: [] };
            if (!list.entries.length) blocks.push(list);
            list.entries.push(current);
          }
        } else {
          var previous = blocks[blocks.length - 1];
          if (!previous || previous.type !== 'list') {
            previous = { type: 'list', items: [] };
            blocks.push(previous);
          }
          previous.items.push(text);
        }
        return;
      }
      /* The Games heading must be followed straight away by the combo box, so
         the README's own pointer to this page is left out here. */
      if (section === 'games' && !current) return;
      blocks.push({ type: 'paragraph', text: raw.trim() });
    });

    blocks.forEach(function (block) {
      if (block.type !== 'games') return;
      var counts = {};
      block.entries.forEach(function (entry) {
        entry.title = entryTitle(entry.line);
        entry.base = entry.section + '/' + slug(entry.title);
        counts[entry.base] = (counts[entry.base] || 0) + 1;
      });
      block.entries.forEach(function (entry) {
        entry.key = entry.base;
        if (counts[entry.base] > 1) {
          var links = [];
          var pattern = linkPattern();
          var match;
          while ((match = pattern.exec(entry.line))) links.push(match[1]);
          entry.key += '/' + slug(links[1] || '');
        }
        describe(entry);
      });
    });
    return blocks;
  }

  /* --- The sort options ------------------------------------------------------ */

  function formatDate(iso) {
    var parts = iso.split('-');
    if (parts.length === 1) return parts[0];
    var month = MONTHS[Number(parts[1]) - 1];
    return (parts[2] ? Number(parts[2]) + ' ' : '') + month + ' ' + parts[0];
  }

  function formatPrice(price) {
    return price === 0 ? 'Free' : '$' + price.toFixed(2);
  }

  function byTitle(a, b) {
    return collator.compare(a.title, b.title);
  }

  function hasPrice(entry) {
    return typeof entry.price === 'number';
  }

  function hasRating(entry) {
    return typeof entry.rating === 'number' && entry.ratingCount >= MIN_RATINGS;
  }

  function monthGroup(entry) {
    if (!entry.added) return 'Added since the data was last refreshed';
    var month = entry.added.slice(0, 7);
    if (historyStart && month === historyStart.slice(0, 7)) return formatDate(month) + ' or earlier';
    return formatDate(month);
  }

  function addedMeta(entry) {
    if (!entry.added) return '';
    if (entry.added === historyStart) return 'Added ' + formatDate(entry.added.slice(0, 7)) + ' or earlier';
    return 'Added ' + formatDate(entry.added);
  }

  function releaseGroup(entry) {
    if (!entry.released) return 'Release date not recorded';
    if (entry.released === 'upcoming') return 'Not released yet';
    return entry.released.slice(0, 4);
  }

  function releaseMeta(entry) {
    if (!entry.released || entry.released === 'upcoming') return '';
    return 'Released ' + formatDate(entry.released);
  }

  function priceGroup(entry) {
    if (!hasPrice(entry)) return NO_PRICE;
    return PRICE_BANDS.filter(function (band) { return band.test(entry.price); })[0].label;
  }

  function priceMeta(entry) {
    var parts = [];
    if (hasPrice(entry)) parts.push(formatPrice(entry.price));
    if (entry.priceNote) parts.push(entry.priceNote);
    return parts.join(' - ');
  }

  function ratingGroup(entry) {
    if (!hasRating(entry)) return NO_RATING;
    return RATING_BANDS.filter(function (band) { return band.test(entry.rating); })[0].label;
  }

  function ratingMeta(entry) {
    if (!hasRating(entry)) return '';
    return entry.rating + '% from ' + entry.ratingCount.toLocaleString('en-US') + ' ratings';
  }

  /* Sorts a value with nothing recorded to the end, whichever way the rest run. */
  function presentFirst(a, b, compare) {
    if (a == null && b == null) return 0;
    if (a == null) return 1;
    if (b == null) return -1;
    return compare(a, b);
  }

  function ascending(a, b) { return a < b ? -1 : a > b ? 1 : 0; }
  function descending(a, b) { return ascending(b, a); }

  function fixedOrder(labels) {
    return function (a, b) { return labels.indexOf(a) - labels.indexOf(b); };
  }

  function labelsOf(list) { return list.map(function (item) { return item.label; }); }

  function checked() { return dataUpdated ? formatDate(dataUpdated) : 'recently'; }

  var HEADINGS_HINT = 'Each group has its own level 3 heading.';
  var SEVERAL_HINT = HEADINGS_HINT + ' A game can appear under more than one.';

  function priceNote() {
    return HEADINGS_HINT + ' Regular US prices for the game only, without sales, checked ' + checked() +
      '. Free games may have in-app purchases. Paid mods are noted where known.';
  }

  function addedNote() {
    return HEADINGS_HINT + ' Dates come from the edit history of this list, which starts in ' +
      formatDate(historyStart.slice(0, 7)) + '.';
  }

  var SORTS = [
    {
      id: 'az', label: 'Alphabetical, A to Z', status: 'Sorted alphabetically, A to Z.',
      within: byTitle
    },
    {
      id: 'za', label: 'Alphabetical, Z to A', status: 'Sorted alphabetically, Z to A.',
      within: function (a, b) { return byTitle(b, a); }
    },
    {
      id: 'added-new', label: 'Date added, newest first', status: 'Sorted by date added, newest first.',
      note: addedNote,
      group: monthGroup, meta: addedMeta,
      value: function (e) { return e.added || '9999'; }, order: descending
    },
    {
      id: 'added-old', label: 'Date added, oldest first', status: 'Sorted by date added, oldest first.',
      note: addedNote,
      group: monthGroup, meta: addedMeta,
      value: function (e) { return e.added || '9999'; }, order: ascending
    },
    {
      id: 'price-low', label: 'Price, lowest first', status: 'Sorted by price, lowest first.',
      note: priceNote,
      group: priceGroup, meta: priceMeta, value: function (e) { return hasPrice(e) ? e.price : null; },
      order: ascending, groupOrder: fixedOrder(labelsOf(PRICE_BANDS).concat(NO_PRICE))
    },
    {
      id: 'price-high', label: 'Price, highest first', status: 'Sorted by price, highest first.',
      note: priceNote,
      group: priceGroup, meta: priceMeta, value: function (e) { return hasPrice(e) ? e.price : null; },
      order: descending, groupOrder: fixedOrder(labelsOf(PRICE_BANDS).reverse().concat(NO_PRICE))
    },
    {
      id: 'access-high', label: 'Accessibility, most accessible first', status: 'Sorted by accessibility, most accessible first.',
      note: function () { return HEADINGS_HINT; },
      group: function (e) { return LEVELS[levelRank(e.access)].label; },
      value: function () { return 0; }, order: ascending,
      groupOrder: fixedOrder(labelsOf(LEVELS))
    },
    {
      id: 'access-low', label: 'Accessibility, least accessible first', status: 'Sorted by accessibility, least accessible first.',
      note: function () { return HEADINGS_HINT; },
      group: function (e) { return LEVELS[levelRank(e.access)].label; },
      value: function () { return 0; }, order: ascending,
      groupOrder: fixedOrder(labelsOf(LEVELS).reverse())
    },
    {
      id: 'setup', label: 'Setup, simplest first', status: 'Sorted by setup, simplest first.',
      note: function () { return HEADINGS_HINT; },
      group: function (e) { return SETUPS.filter(function (s) { return s.id === e.setup; })[0].label; },
      value: function () { return 0; }, order: ascending,
      groupOrder: fixedOrder(labelsOf(SETUPS))
    },
    {
      id: 'audio', label: 'Audio description first', status: 'Sorted with audio description first.',
      note: function () { return HEADINGS_HINT; },
      group: function (e) { return e.audioDescription ? 'Has audio description' : 'No audio description mentioned'; },
      value: function () { return 0; }, order: ascending,
      groupOrder: fixedOrder(['Has audio description', 'No audio description mentioned'])
    },
    {
      id: 'platform', label: 'Platform', status: 'Sorted by platform.',
      note: function () { return SEVERAL_HINT; },
      groups: function (e) {
        var labels = e.platforms.map(function (id) {
          return PLATFORMS.filter(function (p) { return p.id === id; })[0].label;
        });
        return labels.length ? labels : ['Platform not stated'];
      },
      value: function () { return 0; }, order: ascending,
      groupOrder: fixedOrder(labelsOf(PLATFORMS).concat('Platform not stated'))
    },
    {
      id: 'genre', label: 'Genre', status: 'Sorted by genre.',
      note: function () { return SEVERAL_HINT + ' Genres are the ones the stores use.'; },
      groups: function (e) { return e.genres && e.genres.length ? e.genres : ['Genre not recorded']; },
      value: function () { return 0; }, order: ascending,
      groupOrder: function (a, b) {
        if (a === 'Genre not recorded') return 1;
        if (b === 'Genre not recorded') return -1;
        return collator.compare(a, b);
      }
    },
    {
      id: 'released-new', label: 'Release date, newest first', status: 'Sorted by release date, newest first.',
      note: function () { return HEADINGS_HINT; },
      group: releaseGroup, meta: releaseMeta,
      value: function (e) { return e.released || null; }, order: descending
    },
    {
      id: 'released-old', label: 'Release date, oldest first', status: 'Sorted by release date, oldest first.',
      note: function () { return HEADINGS_HINT; },
      group: releaseGroup, meta: releaseMeta,
      value: function (e) { return e.released || null; }, order: ascending
    },
    {
      id: 'rating', label: 'Store rating, highest first', status: 'Sorted by store rating, highest first.',
      note: function () { return HEADINGS_HINT + ' Store ratings are about the game in general, not its accessibility. They come from Steam, through SteamSpy, and the App Store, checked ' + checked() + '.'; },
      group: ratingGroup, meta: ratingMeta,
      value: function (e) { return hasRating(e) ? e.rating : null; }, order: descending,
      groupOrder: fixedOrder(labelsOf(RATING_BANDS).concat(NO_RATING))
    }
  ];

  /* --- Drawing --------------------------------------------------------------- */

  function renderEntry(entry, sort) {
    var li = document.createElement('li');
    appendTokens(li, entry.tokens);
    var meta = sort.meta ? sort.meta(entry) : '';
    if (meta) li.appendChild(document.createTextNode(' - ' + meta.replace(/\.$/, '')));
    if (entry.children.length) {
      var ul = document.createElement('ul');
      entry.children.forEach(function (child) {
        var sub = document.createElement('li');
        appendTokens(sub, tokenize(child));
        ul.appendChild(sub);
      });
      li.appendChild(ul);
    }
    return li;
  }

  function renderList(entries, sort) {
    var ul = document.createElement('ul');
    entries.forEach(function (entry) { ul.appendChild(renderEntry(entry, sort)); });
    return ul;
  }

  function sortEntries(entries, sort) {
    return entries.slice().sort(function (a, b) {
      var result = 0;
      if (sort.value) result = presentFirst(sort.value(a), sort.value(b), sort.order);
      return result || (sort.within || byTitle)(a, b);
    });
  }

  function renderSection(container, entries, sort) {
    var sorted = sortEntries(entries, sort);
    var fragment = document.createDocumentFragment();
    var groupsOf = sort.groups || (sort.group && function (entry) { return [sort.group(entry)]; });

    if (!groupsOf) {
      fragment.appendChild(renderList(sorted, sort));
    } else {
      var groups = new Map();
      sorted.forEach(function (entry) {
        groupsOf(entry).forEach(function (label) {
          if (!groups.has(label)) groups.set(label, []);
          groups.get(label).push(entry);
        });
      });
      var labels = Array.from(groups.keys());
      if (sort.groupOrder) labels.sort(sort.groupOrder);
      labels.forEach(function (label) {
        var heading = document.createElement('h3');
        var count = groups.get(label).length;
        heading.textContent = label + ': ' + count + (count === 1 ? ' game' : ' games');
        fragment.appendChild(heading);
        fragment.appendChild(renderList(groups.get(label), sort));
      });
    }
    container.replaceChildren(fragment);
  }

  function renderBlocks(blocks) {
    var page = document.getElementById('page');
    var fragment = document.createDocumentFragment();
    var lists = [];

    blocks.forEach(function (block) {
      var node;
      if (block.type === 'heading') {
        node = document.createElement('h' + Math.min(block.level, 6));
        node.textContent = block.text;
        node.id = slug(block.text);
        fragment.appendChild(node);
        if (block.section === 'games') fragment.appendChild(buildControl());
      } else if (block.type === 'paragraph') {
        node = document.createElement('p');
        appendTokens(node, tokenize(repairLine(block.text)));
        fragment.appendChild(node);
      } else if (block.type === 'list') {
        node = document.createElement('ul');
        block.items.forEach(function (text) {
          var li = document.createElement('li');
          appendTokens(li, tokenize(text));
          node.appendChild(li);
        });
        fragment.appendChild(node);
      } else if (block.type === 'rule') {
        fragment.appendChild(document.createElement('hr'));
      } else if (block.type === 'games') {
        node = document.createElement('div');
        lists.push({ container: node, entries: block.entries });
        fragment.appendChild(node);
      }
    });
    page.replaceChildren(fragment);
    return lists;
  }

  function buildControl() {
    var wrapper = document.createDocumentFragment();

    var control = document.createElement('div');
    control.className = 'sort-control';
    var label = document.createElement('label');
    label.htmlFor = 'sort';
    label.textContent = 'Sort all games on this page by';
    var select = document.createElement('select');
    select.id = 'sort';
    SORTS.forEach(function (sort) {
      var option = document.createElement('option');
      option.value = sort.id;
      option.textContent = sort.label;
      select.appendChild(option);
    });
    control.appendChild(label);
    control.appendChild(select);
    wrapper.appendChild(control);

    /* Announced by screen readers when it changes. Kept short on purpose; the
       longer explanation goes in the note below, which is only read if wanted. */
    var status = document.createElement('p');
    status.id = 'sort-status';
    status.setAttribute('role', 'status');
    wrapper.appendChild(status);

    var note = document.createElement('p');
    note.id = 'sort-note';
    wrapper.appendChild(note);
    return wrapper;
  }

  function wireControl(lists) {
    var select = document.getElementById('sort');
    var status = document.getElementById('sort-status');
    var note = document.getElementById('sort-note');
    var timer = null;

    function apply() {
      var sort = SORTS.filter(function (s) { return s.id === select.value; })[0] || SORTS[0];
      lists.forEach(function (list) { renderSection(list.container, list.entries, sort); });
      note.textContent = sort.note ? sort.note() : '';
      note.hidden = !sort.note;
      status.textContent = sort.status;
    }

    /* Arrowing through a closed combo box fires a change for every option. Wait
       for a pause, so the list is not redrawn and announced for each one. */
    select.addEventListener('change', function () {
      clearTimeout(timer);
      timer = setTimeout(function () {
        try {
          var url = new URL(location.href);
          if (select.value === SORTS[0].id) url.searchParams.delete('sort');
          else url.searchParams.set('sort', select.value);
          history.replaceState(null, '', url);
        } catch (error) { /* the address just does not update */ }
        apply();
      }, 450);
    });

    var wanted = new URLSearchParams(location.search).get('sort');
    if (SORTS.some(function (s) { return s.id === wanted; })) select.value = wanted;
    apply();
  }

  /* --- Starting up ----------------------------------------------------------- */

  function fetchText(path) {
    return fetch(path, { cache: 'no-cache' }).then(function (response) {
      if (!response.ok) throw new Error(path + ': ' + response.status);
      return response.text();
    });
  }

  function fetchJson(path) {
    /* The page still works without the extra data, with fewer facts to sort on. */
    return fetch(path, { cache: 'no-cache' }).then(function (response) {
      return response.ok ? response.json() : {};
    }).catch(function () { return {}; });
  }

  function mergeFacts(blocks, data, overrides) {
    dataUpdated = data.updated || '';
    historyStart = data.historyStart || '';
    var facts = data.entries || {};
    blocks.forEach(function (block) {
      if (block.type !== 'games') return;
      block.entries.forEach(function (entry) {
        Object.assign(entry, facts[entry.key] || {}, overrides[entry.key] || {});
      });
    });
  }

  Promise.all([fetchText('README.md'), fetchJson('data/games.json'), fetchJson('data/overrides.json')])
    .then(function (results) {
      var blocks = parseEntries(results[0]);
      mergeFacts(blocks, results[1], results[2]);
      wireControl(renderBlocks(blocks));
      if (location.hash) {
        var target = document.getElementById(location.hash.slice(1));
        if (target) target.scrollIntoView();
      }
    })
    .catch(function () {
      var page = document.getElementById('page');
      page.textContent = '';
      var message = document.createElement('p');
      message.setAttribute('role', 'alert');
      message.textContent = 'The list could not be loaded. ';
      var link = document.createElement('a');
      link.href = 'https://github.com/Molitvan/blind-accessible-games-list#readme';
      link.textContent = 'Read it on GitHub instead.';
      message.appendChild(link);
      page.appendChild(message);
    });
}());
